    const pool = new TaskPool(runtime.scheduler, maxConcurrency);

    return {
      go: class extends PoolMethodBuilder {
        override call() {
          const [callback] = this.args;
          this.validateFunction(callback);

          return this.handle(pool.go(this.job(callback)));
